import os, json, ssl, base64
import urllib.request, urllib.parse
import urllib.error

tu_url  = os.environ.get('TUONI_API_URL', '').strip()
tu_user = os.environ.get('TUONI_USERNAME', '').strip()
tu_pass = os.environ.get('TUONI_PASSWORD', '')

# The shipped .env carries REPLACE_WITH_* placeholders. Treat those as "not
# configured" so a stack that never wired up Tuoni does not attempt a doomed
# connection on every 5-minute tick.
def _placeholder(v):
    return v.upper().startswith('REPLACE_WITH')

if not tu_url or _placeholder(tu_url):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'TUONI_API_URL is not set (or still the .env placeholder)',
                      'agents': [], 'listeners': {}}}]
if not tu_user or _placeholder(tu_user):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'TUONI_USERNAME is not set (or still the .env placeholder)',
                      'agents': [], 'listeners': {}}}]
if _placeholder(tu_pass):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'TUONI_PASSWORD is still the .env placeholder',
                      'agents': [], 'listeners': {}}}]

# NO PATH PREFIX, unlike Adaptix: TUONI_API_URL is just scheme://host:port
# (default port 8443) and the API paths are fixed.
base = tu_url.rstrip('/')

# The teamserver's TLS is operator-generated and typically self-signed, exactly as
# with the Cobalt Strike team server in workflow 01 and Adaptix in workflow 28.
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE


def _req(url, data=None, headers=None, method='GET'):
    req = urllib.request.Request(url, data=data, headers=headers or {}, method=method)
    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        return r.read()


# -- Step 1: authenticate (HTTP Basic -> Bearer accessToken) -------------------
# Tuoni issues no static API token; a short-lived accessToken (~15 min) is minted
# per login. Each n8n run is a fresh process with nowhere to cache one, so at a
# 5-minute cadence a login per poll is cheaper than /refresh bookkeeping. The
# login endpoint takes an Authorization: Basic header, NOT a JSON body. A rejected
# login is a plain 401 (no 404 trap, unlike Adaptix).
try:
    basic = base64.b64encode((tu_user + ':' + tu_pass).encode('utf-8')).decode('ascii')
    raw = _req(base + '/api/v2/auth/login', data=b'',
               headers={'Authorization': 'Basic ' + basic}, method='POST')
    token = ''
    try:
        token = (json.loads(raw) or {}).get('accessToken', '')
    except Exception:
        # The deprecated v1 login returns the raw JWT as the whole body.
        token = raw.decode('utf-8', 'replace').strip()
    if not token:
        return [{'json': {'fetch_ok': False, 'agents': [], 'listeners': {},
                          'error': 'Tuoni login returned no accessToken'}}]
except urllib.error.HTTPError as e:
    return [{'json': {'fetch_ok': False, 'agents': [], 'listeners': {},
                      'error': ('Tuoni login HTTP ' + str(e.code) +
                                ' (401 almost always means bad credentials)')}}]
except Exception as e:
    return [{'json': {'fetch_ok': False, 'agents': [], 'listeners': {},
                      'error': 'Tuoni login failed: ' + repr(e)}}]

auth_hdr = {'Authorization': 'Bearer ' + token}

# -- Step 2: listeners map (best-effort; a failure only blanks one column) -----
listeners = {}
try:
    ldata = json.loads(_req(base + '/api/v1/listeners', headers=auth_hdr))
    if isinstance(ldata, dict):
        inner = None
        for key in ('items', 'listeners', 'data'):
            if isinstance(ldata.get(key), list):
                inner = ldata[key]
                break
        if inner is not None:
            for l in inner:
                if isinstance(l, dict) and l.get('id') is not None:
                    listeners[str(l['id'])] = str(l.get('name') or l['id'])
        else:
            for lid, l in ldata.items():
                nm = l.get('name') if isinstance(l, dict) else None
                listeners[str(lid)] = str(nm or lid)
    elif isinstance(ldata, list):
        for l in ldata:
            if isinstance(l, dict) and l.get('id') is not None:
                listeners[str(l['id'])] = str(l.get('name') or l['id'])
except Exception:
    listeners = {}

# -- Step 3: pull the roster (prefer v2 pagination, fall back to v1) -----------
# No status filter, so ACTIVE and INACTIVE both come back and WF23 decides
# stale/dead from lastCallbackTime rather than this node.
try:
    agents = []
    try:
        page = 0
        while page < 1000:
            q = urllib.parse.urlencode({'page': page, 'pageSize': 200})
            payload = json.loads(_req(base + '/api/v2/agents?' + q, headers=auth_hdr))
            if isinstance(payload, list):
                agents = payload
                break
            if not isinstance(payload, dict):
                break
            batch = None
            for key in ('items', 'content', 'agents', 'data'):
                if isinstance(payload.get(key), list):
                    batch = payload[key]
                    break
            if batch is None:
                break
            agents.extend(batch)
            if not payload.get('hasMorePages'):
                break
            page += 1
    except urllib.error.HTTPError:
        # v2 unavailable -> v1, which may answer with a bare array OR a dict.
        vdata = json.loads(_req(base + '/api/v1/agents', headers=auth_hdr))
        if isinstance(vdata, list):
            agents = vdata
        elif isinstance(vdata, dict):
            inner = None
            for key in ('items', 'agents', 'data'):
                if isinstance(vdata.get(key), list):
                    inner = vdata[key]
                    break
            if inner is not None:
                agents = inner
            else:
                agents = [v for v in vdata.values() if isinstance(v, dict)]
        else:
            agents = []

    return [{'json': {'fetch_ok': True, 'error': '', 'agents': agents,
                      'listeners': listeners}}]
except urllib.error.HTTPError as e:
    body = ''
    try:
        body = e.read().decode('utf-8', errors='replace')[:300]
    except Exception:
        body = ''
    return [{'json': {'fetch_ok': False, 'agents': [], 'listeners': {},
                      'error': 'Tuoni API HTTP ' + str(e.code) + ': ' + body}}]
except Exception as e:
    return [{'json': {'fetch_ok': False, 'agents': [], 'listeners': {},
                      'error': 'Tuoni API request failed: ' + repr(e)}}]
